 async function get(url,binary=false){const r=await fetch(url,{signal:AbortSignal.timeout(70000)});if(!r.ok){let error=`Data service returned ${r.status}`;try{error=(await r.json()).error||error}catch{}throw Error(error)}return binary?r.arrayBuffer():r.json();}
 function preparedExposure(row,position){const key=`${row.access_url}|${position.ra.toFixed(6)}|${position.dec.toFixed(6)}`;if(projectedCache.has(key)){const cached=projectedCache.get(key);projectedCache.delete(key);projectedCache.set(key,cached);return cached;}const pending=(async()=>{const url=row.local||(API_BASE+'/archive?'+new URLSearchParams({ra:position.ra,dec:position.dec,file:new URL(row.access_url).pathname,size:'.4'}));const parsed=parseFits(await get(url,true));return {image:{h:parsed.h},sample:spectralProject(parsed,position.ra,position.dec,FOV,N)};})();projectedCache.set(key,pending);while(projectedCache.size>4)projectedCache.delete(projectedCache.keys().next().value);pending.catch(()=>projectedCache.delete(key));return pending;}
