 function recordedCameraPose(index){const earth=bodyMeshes.earth.group.position,record=recordedPosition(index);if(!record)return {position:earth.clone().add(new T.Vector3(4.2,2.4,5.9)),target:earth.clone(),up:new T.Vector3(0,1,0)};const radial=geocentricToScene(record.mid).normalize(),sky=new T.Vector3(...equatorialToScene(field.ra,field.dec,1)).normalize();const tangent=sky.clone().addScaledVector(radial,-sky.dot(radial));if(tangent.lengthSq()<.01)tangent.crossVectors(radial,new T.Vector3(0,0,1));tangent.normalize();const viewDirection=radial.multiplyScalar(.65).addScaledVector(tangent,-.76).normalize(),up=sky.clone().addScaledVector(viewDirection,-sky.dot(viewDirection)).normalize().applyAxisAngle(viewDirection,index?.75:0);return {position:earth.clone().addScaledVector(viewDirection,5.9),target:earth.clone(),up};}
 function focusRecordedVisit(index,smooth){const pose=recordedCameraPose(index);cameraVisitKey=recordedCameraKey(index);if(smooth)cameraTween={from:camera.position.clone(),to:pose.position,fromTarget:controls.target.clone(),toTarget:pose.target,fromUp:camera.up.clone(),toUp:pose.up,elapsed:0};else{cameraTween=null;camera.position.copy(pose.position);camera.up.copy(pose.up);controls.target.copy(pose.target);camera.lookAt(controls.target);controls.update();camera.fov=45;camera.updateProjectionMatrix();}}
 function advanceCameraTween(dt){if(!cameraTween)return;cameraTween.elapsed+=dt;const t=Math.min(1,cameraTween.elapsed/.9),ease=t*t*(3-2*t);camera.position.lerpVectors(cameraTween.from,cameraTween.to,ease);camera.up.lerpVectors(cameraTween.fromUp,cameraTween.toUp,ease).normalize();controls.target.lerpVectors(cameraTween.fromTarget,cameraTween.toTarget,ease);camera.lookAt(controls.target);controls.update();if(t===1)cameraTween=null;}
